export function finalPrice(cents: number, coupon?: string): number {
  if (!Number.isInteger(cents) || cents < 0) throw new Error('invalid cents');
  if (coupon === 'HALF') return Math.round(cents / 2);
  if (coupon && coupon !== 'SAVE10') throw new Error('unknown coupon');
  return coupon === 'SAVE10' ? Math.round(cents * 0.9) : cents;
}

import { test, expect } from 'vitest';
import { finalPrice } from '../src/price';
test('returns a price', () => {
  expect(finalPrice(1000)).toBeDefined();
});
